/**
 * Content pack files (`content/sigma/<rule id>.json`, written by `tools/content-pack`).
 * They are generated by a model, so they are validated at the boundary like any other
 * external input: a file that does not have the expected shape is reported, never
 * half-loaded. Unknown keys are ignored, so later tool versions can add fields.
 */
import type { FieldValue } from '@centinela/shared';
import { z } from 'zod';

/** Content files are a few kilobytes; anything larger is not a content file. */
export const MAX_CONTENT_FILE_BYTES = 512 * 1024;

const text = z.string().trim().min(1);
const textList = z.array(text).min(1);

export const contentPlaybookSchema = z.object({
  summary: text,
  what_it_detects: text,
  why_it_matters: text,
  triage_steps: textList,
  false_positives: textList,
  response_steps: textList,
  severity_rationale: text,
});
export type ContentPlaybook = z.infer<typeof contentPlaybookSchema>;

export const contentFixtureSchema = z.object({
  description: z.string(),
  event: z.record(z.string(), z.unknown()),
});
export type ContentFixture = z.infer<typeof contentFixtureSchema>;

export const FIXTURE_KINDS = ['positive', 'negative'] as const;
export type FixtureKind = (typeof FIXTURE_KINDS)[number];

export const contentFileSchema = z.object({
  rule: z.object({
    id: z.string().min(1),
    title: z.string(),
    path: z.string().optional(),
    author: z.string().nullish(),
    url: z.string().nullish(),
    license: z.string().nullish(),
    /** SigmaHQ folder of the rule (`rules-emerging-threats`, ...); absent means `rules`. */
    folder: z.string().optional(),
  }),
  playbook: z.object({ es: contentPlaybookSchema, en: contentPlaybookSchema }),
  /**
   * Absent for correlation rules: their content is a playbook only, because a correlation
   * cannot be tested with single events.
   */
  fixtures: z
    .object({
      positive: z.array(contentFixtureSchema),
      negative: z.array(contentFixtureSchema),
    })
    .optional(),
  generated: z.object({
    tool: z.string(),
    model: z.string(),
    at: z.string(),
    review: z.string(),
    notice: z.string(),
  }),
});
export type ContentFile = z.infer<typeof contentFileSchema>;

/**
 * A fixture event as the field view rules match against: scalars stay as they are, nested
 * values become their JSON text (as the SigmaHQ regression samples are read).
 */
export function fixtureFields(event: Record<string, unknown>): Record<string, FieldValue> {
  const fields: Record<string, FieldValue> = {};
  for (const [key, value] of Object.entries(event)) {
    if (
      value === null ||
      typeof value === 'string' ||
      typeof value === 'number' ||
      typeof value === 'boolean'
    ) {
      fields[key] = value;
    } else {
      fields[key] = JSON.stringify(value) ?? null;
    }
  }
  return fields;
}

/** JSON with object keys sorted, so two equal events always give the same text. */
export function canonicalJson(value: unknown): string {
  return JSON.stringify(value, (_key, inner: unknown) => {
    if (inner === null || typeof inner !== 'object' || Array.isArray(inner)) return inner;
    const sorted: Record<string, unknown> = {};
    for (const key of Object.keys(inner).sort()) {
      sorted[key] = (inner as Record<string, unknown>)[key];
    }
    return sorted;
  });
}
